import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/codex/commands.md","filePath":"modules/codex/commands.md","lastUpdated":0}`),a={name:`modules/codex/commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to “命令与权限”">​</a></h1><p>EmakiCodex 的主命令是 <code>/codex</code>，别名为 <code>/ecodex</code>。<code>codex</code> 与 <code>open</code> 都会打开分类条目图鉴 GUI；文档示例统一使用 <code>/codex</code>。</p><p>普通入口检查 <code>emakicodex.use</code>；<code>emakicodex.admin</code> 可作为 <code>use</code>、<code>reload</code> 和 <code>debug</code> 的旁路。所有管理目标目前都要求在线玩家。</p><h2 id="命令列表" tabindex="-1">命令列表 <a class="header-anchor" href="#命令列表" aria-label="Permalink to “命令列表”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/codex</code> / <code>/codex help</code></td><td><code>emakicodex.use</code></td><td>显示帮助。</td></tr><tr><td><code>/codex codex</code> / <code>/codex open</code></td><td><code>emakicodex.use</code> 或 <code>emakicodex.admin</code></td><td>打开分类条目图鉴 GUI。</td></tr><tr><td><code>/codex reload</code></td><td><code>emakicodex.reload</code> 或 <code>emakicodex.admin</code></td><td>重载配置、语言、原版成就页和分类条目，重建注册内容，并尝试向在线玩家重推。</td></tr><tr><td><code>/codex grant &lt;player&gt; &lt;advId&gt;</code></td><td><code>emakicodex.admin</code></td><td>授予在线玩家一个原版 Codex Advancement 节点。</td></tr><tr><td><code>/codex revoke &lt;player&gt; &lt;advId&gt;</code></td><td><code>emakicodex.admin</code></td><td>撤销在线玩家一个原版 Codex Advancement 节点。</td></tr><tr><td><code>/codex admin unlock &lt;player&gt; &lt;category/entry&gt;</code></td><td><code>emakicodex.admin</code></td><td>直接解锁一个分类条目，不执行激活或领取。</td></tr><tr><td><code>/codex admin reset &lt;player&gt; [category/entry]</code></td><td><code>emakicodex.admin</code></td><td>重置一个分类条目，省略复合 id 时重置该玩家全部分类条目状态。</td></tr><tr><td><code>/codex debug ...</code></td><td><code>emakicodex.debug</code> 或 <code>emakicodex.admin</code></td><td>管理 <code>advancement</code> debug 模块。具体子命令由 CoreLib DebugCommand 提供。</td></tr></tbody></table><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/codex</span></span>
<span class="line"><span>/codex codex</span></span>
<span class="line"><span>/codex open</span></span>
<span class="line"><span>/codex reload</span></span>
<span class="line"><span>/codex grant Steve example/first_step</span></span>
<span class="line"><span>/codex grant Steve emakicodex:example/challenge</span></span>
<span class="line"><span>/codex revoke Steve example/first_step</span></span>
<span class="line"><span>/codex admin unlock Steve example/first_blood</span></span>
<span class="line"><span>/codex admin reset Steve example/first_blood</span></span>
<span class="line"><span>/codex admin reset Steve</span></span>
<span class="line"><span>/codex debug advancement on</span></span>
<span class="line"><span>/codex debug advancement off</span></span></code></pre></div><p><code>grant</code> 与 <code>revoke</code> 的目标玩家必须在线，因为当前实现使用在线玩家名精确匹配。<code>admin unlock/reset</code> 的目标玩家也必须在线。原版节点的 <code>advId</code> 支持两种写法：</p><table tabindex="0"><thead><tr><th>写法</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>page/node</code></td><td><code>example/first_step</code></td><td>推荐给服主使用的短写。</td></tr><tr><td>完整 NamespacedKey</td><td><code>emakicodex:example/first_step</code></td><td>与底层原版 Advancement key 一致。</td></tr></tbody></table><p>分类条目命令不使用原版 NamespacedKey，而使用 <code>codex/*.yml</code> 的复合 id：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;category_id&gt;/&lt;entry_id&gt;</span></span></code></pre></div><p>例如 <code>example/first_blood</code>。<code>admin unlock</code> 只改变“已解锁”状态；GUI 中的左键激活会另外开启属性奖励，右键领取才会执行一次性 <code>rewards.actions</code>。</p><h2 id="reload-行为" tabindex="-1">reload 行为 <a class="header-anchor" href="#reload-行为" aria-label="Permalink to “reload 行为”">​</a></h2><p><code>/codex reload</code> 会执行以下工作：</p><ol><li>释放缺失的默认资源，受 <code>config.yml &gt; release_default_data</code> 控制。</li><li>重新读取 <code>config.yml</code>、<code>lang/*.yml</code>、<code>advancements/*.yml</code>、<code>codex/*.yml</code> 与 GUI 模板。</li><li>移除并重新注册 EmakiCodex 命名空间下的动态 Advancement，并重建分类条目与奖励提供器。</li><li>如果 PacketEvents 可用，向在线玩家重推原版成就树；否则在线玩家可能需要重新登录才能看到原版成就界面变化。</li><li>玩家分类条目数据保留在 <code>data/&lt;uuid&gt;.yml</code>，奖励属性按新配置重新推导。</li></ol><h2 id="权限节点" tabindex="-1">权限节点 <a class="header-anchor" href="#权限节点" aria-label="Permalink to “权限节点”">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>覆盖范围</th></tr></thead><tbody><tr><td><code>emakicodex.use</code></td><td><code>true</code></td><td>使用帮助、打开分类条目 GUI（<code>codex/open</code>）和普通入口。</td></tr><tr><td><code>emakicodex.reload</code></td><td><code>op</code></td><td>使用 <code>/codex reload</code>。可被 <code>emakicodex.admin</code> 代替。</td></tr><tr><td><code>emakicodex.debug</code></td><td><code>op</code></td><td>使用 <code>/codex debug ...</code>。可被 <code>emakicodex.admin</code> 代替。</td></tr><tr><td><code>emakicodex.admin</code></td><td><code>op</code></td><td>使用 <code>grant</code>、<code>revoke</code>、<code>admin unlock/reset</code>，并可代替 use/reload/debug 专用权限。</td></tr></tbody></table><p>常见 LuckPerms 示例：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/lp group default permission set emakicodex.use true</span></span>
<span class="line"><span>/lp group admin permission set emakicodex.admin true</span></span>
<span class="line"><span>/lp group admin permission set emakicodex.reload true</span></span>
<span class="line"><span>/lp group admin permission set emakicodex.debug true</span></span></code></pre></div><h2 id="常见失败原因" tabindex="-1">常见失败原因 <a class="header-anchor" href="#常见失败原因" aria-label="Permalink to “常见失败原因”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>说明</th></tr></thead><tbody><tr><td><code>Player not found</code></td><td><code>grant</code> / <code>revoke</code> 的目标玩家不在线，或玩家名不完全匹配。</td></tr><tr><td><code>Advancement ... 未注册或状态无变化</code></td><td>成就 ID 写错、页面未成功加载，或授予/撤销时玩家当前进度没有变化。</td></tr><tr><td><code>category/entry</code> 找不到</td><td>分类文件未加载、复合 id 拼写错误，或条目仍未解锁。</td></tr><tr><td><code>admin unlock</code> 成功但没有属性</td><td><code>unlock</code> 只改变解锁态；还要在 GUI 左键激活，且属性奖励来自 <code>rewards.attributes</code>。</td></tr><tr><td>右键领取失败</td><td>条目未解锁、没有 <code>rewards.actions</code>，或已经领取过；领取是一次性状态。</td></tr><tr><td>在线玩家看不到 reload 后的新成就树</td><td>未安装 PacketEvents 或重推失败时，在线玩家需要重新登录。</td></tr><tr><td>节点坐标不生效</td><td>需要安装 PacketEvents，并开启 <code>advancement.packet_coordinates: true</code>。</td></tr></tbody></table>`,21)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};